        "title": "材料与表面方案",
        "paragraphs": [
          "展陈方向：使用低饱和底色与局部高光，强调主体轮廓和层次。",
          "材料方向：按受力与表面需求选择树脂、PLA/PETG或混合制作，并先做接口试件。",
          "表面方向：可选自然材质、金属旧化或高对比图形化处理，分别建立底色、阴影和保护层。"
        ]
